package com.example.rokidkeyboardbridge;
import org.json.*;
public class ReleaseReliabilityGlassTest {
 static int count;static void check(boolean yes){count++;if(!yes)throw new AssertionError("glass case "+count);}
 public static void main(String[] args)throws Exception{long now=System.currentTimeMillis();JSONArray rows=new JSONArray();rows=DeferredNotificationDigest.add(rows,"normal","合成の完了通知","completed",now,now);check(rows.length()==1);rows=DeferredNotificationDigest.add(rows,"question","合成の確認質問","question",now,now);check(DeferredNotificationDigest.unread(rows,now).getJSONObject(0).getString("id").equals("question"));check(DeferredNotificationDigest.label(rows,now).contains("確認待ち 1件"));check(DeferredNotificationDigest.add(rows,"question","別の本文","question",now+1,now+1).length()==2);JSONArray shown=DeferredNotificationDigest.unread(rows,now);rows=DeferredNotificationDigest.add(rows,"new","合成の状態通知","status",now,now);rows=DeferredNotificationDigest.markRead(rows,shown,now);check(DeferredNotificationDigest.seen(rows,"question"));check(DeferredNotificationDigest.unread(rows,now).length()==1);check(DeferredNotificationDigest.add(rows,"old","古い通知","status",now-600000,now)==null);check(DeferredNotificationDigest.add(rows,"x","通知","invalid",now,now)==null);for(int i=0;i<17;i++)rows=DeferredNotificationDigest.add(rows,"fill"+i,"通知","status",now,now);check(rows.length()==20);check(DeferredNotificationDigest.add(rows,"overflow","通知","status",now,now)==null);check(DeferredNotificationDigest.alive(rows,now+600000).length()==0);check(ConversationFollowupPolicy.referencesPrevious("それはいくら？"));check(ConversationFollowupPolicy.referencesPrevious("ほかには？"));check(!ConversationFollowupPolicy.referencesPrevious("別の話。ニュース調べて"));System.out.println("PASS glass reliability "+count);}
}
